+const addToBagButtons = document.querySelectorAll(".add-to-bag");
+const announcementElement = document.getElementById("announcement-banner");
+const dismissAnnouncementButton = document.getElementById("dismiss-announcement");
+
+let bagCount = 0;
+let statusTimeoutId;
+
+function showStatusMessage(message) {
+  statusMessageElement.textContent = message;
+  statusMessageElement.classList.add("is-visible");
+
+  window.clearTimeout(statusTimeoutId);
+  statusTimeoutId = window.setTimeout(() => {
+    statusMessageElement.classList.remove("is-visible");
+  }, 2200);
+}
+
+addToBagButtons.forEach((button) => {
+  button.addEventListener("click", () => {
+    const productName = button.dataset.product;
+
+    bagCount += 1;
+    bagCountElement.textContent = String(bagCount);
+    showStatusMessage(`${productName} added to bag.`);
+  });
+});
+
+dismissAnnouncementButton.addEventListener("click", () => {
+  announcementElement.hidden = true;
+  showStatusMessage("Shipping promotion dismissed.");
