         box-sizing: border-box;
       }

       html {
         scroll-behavior: smooth;
       }

       body {
         margin: 0;
         font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
         background:
           radial-gradient(circle at top left, rgba(217, 119, 87, 0.15), transparent 22rem),
           linear-gradient(180deg, #fbf8f4 0%, var(--bg) 100%);
         color: var(--text);
         line-height: 1.5;
       }

       a {
         color: inherit;
       }

       .skip-link {
         position: absolute;
         left: 1rem;
         top: 1rem;
         z-index: 100;
         padding: 0.75rem 1rem;
         border-radius: 999px;
         background: var(--surface-accent);
         color: #fff;
         text-decoration: none;
         transform: translateY(-200%);
       }

       .skip-link:focus {
         transform: translateY(0);
       }

       .site-shell {
         width: var(--container);
         margin: 0 auto;
         padding: 20px 0 40px;
