         border: 1px solid var(--line);
         background: var(--surface);
         box-shadow: var(--shadow);
       }

       .announcement {
         display: flex;
         align-items: center;
         justify-content: space-between;
         gap: 1rem;
         margin-bottom: 16px;
         padding: 0.9rem 1.2rem;
         border-radius: var(--radius-sm);
       }

       .announcement__text {
         margin: 0;
         font-size: 0.95rem;
         color: var(--brand-dark);
         font-weight: 600;
       }

       .announcement__button {
         border: 0;
         background: transparent;
         color: var(--brand-dark);
         font: inherit;
         font-weight: 700;
         cursor: pointer;
       }

       .topbar {
         display: flex;
         align-items: center;
         justify-content: space-between;
         gap: 1rem;
         padding: 1rem 1.25rem;
         border-radius: var(--radius-lg);
       }

       .brand,
       .cart-link,
       .primary-nav a,
       .button,
       .deal-card__link,
       .section__link,
       .hero-panel__link,
       .footer-links a,
       .story-card a {
         text-decoration: none;
       }

       .brand {
         display: inline-flex;
         align-items: center;
         gap: 0.85rem;
         font-weight: 800;
       }

       .brand__mark {
