         width: 2.5rem;
         height: 2.5rem;
         border-radius: 50%;
         background: linear-gradient(135deg, var(--brand), var(--accent));
         color: #fff;
         letter-spacing: 0.05em;
       }

       .primary-nav {
         display: inline-flex;
         flex-wrap: wrap;
         justify-content: center;
         gap: 0.35rem;
       }

       .primary-nav a,
