         padding: 0.75rem 1rem;
         border-radius: 999px;
         color: var(--muted);
         font-weight: 600;
       }

       .cart-link {
         display: inline-flex;
         align-items: center;
         gap: 0.65rem;
         background: var(--surface-strong);
       }

       .cart-link__count {
         display: inline-grid;
         place-items: center;
         min-width: 1.9rem;
         height: 1.9rem;
         padding: 0 0.4rem;
         border-radius: 999px;
         background: var(--surface-accent);
         color: #fff;
         font-size: 0.9rem;
       }

       .hero {
         display: grid;
         grid-template-columns: minmax(0, 1.6fr) minmax(280px, 0.9fr);
         gap: 1.5rem;
         margin: 20px 0;
         padding: clamp(1.5rem, 3vw, 2.5rem);
         border-radius: var(--radius-xl);
       }

       .eyebrow,
       .hero-panel__label,
       .product-card__category,
       .deal-card__tag,
       .story-card__kicker {
         margin: 0 0 0.7rem;
         text-transform: uppercase;
         letter-spacing: 0.12em;
         font-size: 0.74rem;
         font-weight: 800;
         color: var(--brand);
       }

       .hero h1,
       .section h2 {
         margin: 0;
         line-height: 1.05;
         letter-spacing: -0.04em;
       }

       .hero h1 {
         max-width: 11ch;
         font-size: clamp(2.8rem, 8vw, 5.4rem);
